const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const term=id=>TERMS.find(t=>t.id===id),refs=ids=>ids.map(id=>{const s=COST_SOURCES[id];return `<a href="${s[1]}" target="_blank" rel="noopener">${esc(s[0])} ↗</a>`}).join('');
let cat=-1,selected='raw';
window.SCENES={
 fabflow:{title:'從原片，到電晶體與配線',en:'01 / WAFER TO CIRCUIT',sub:'放大右側結構，分清元件與互連；圖形僅示意。',default:'raw',parts:[['raw','原片'],['flow','製程分段'],['nanosheet','奈米片'],['metal','金屬互連']]},
 lithography:{title:'圖形，如何到達晶圓？',en:'02 / PATTERN TRANSFER',sub:'拆開模板、光學示意與感光層；不是 EUV 真實光路。',default:'lithography',parts:[['lithography','曝光機'],['mask','光罩'],['euv','曝光技術'],['resist','光阻'],['track','塗佈顯影']]},
 chamber:{title:'一個腔體，多種成本',en:'03 / MATERIAL ENGINEERING',sub:'拆開上蓋，看氣體、製程區與真空如何協作。',default:'etch',parts:[['etch','蝕刻'],['ald','沉積'],['chamberparts','腔體零件'],['specialgas','製程氣體'],['vacuum','真空幫浦']]},
 polishing:{title:'讓下一層，有平整的起點',en:'04 / PLANARIZATION',sub:'向上拆開載具，查看研磨墊、研磨液與後清洗。',default:'cmp',parts:[['cmp','CMP'],['pad','墊與修整器'],['slurry','研磨液'],['raw','晶圓'],['wetclean','後清洗']]},
 costpackage:{title:'連接之前，也要驗證',en:'05 / PACKAGING & TEST',sub:'載板、接合與測試介面，代表不同成本對象。',default:'bonding',parts:[['package','封裝材料'],['bonding','接合'],['probe','測試介面'],['dicing','薄化切割']]},
 facility:{title:'製程之外，還有一整座工廠',en:'06 / FAB UTILITIES',sub:'展開樓層，探索潔淨室、超純水、公用系統與尾氣處理。',default:'cleanroom',parts:[['cleanroom','廠房與空調'],['lithography','生產機台'],['upw','超純水'],['electricity','電力公用'],['abatement','尾氣處理'],['amhs','自動搬運']]}
};
function companyHTML(t){const note=t.companyNote||'依公開產品或服務列舉。實際歸集須區分材料製造、代理、設備、零件與工程服務。';if(!t.companies.length)return `<p class="company-note">${esc(t.companyNote||'這是會計或製程概念，未列可直接對應的台股產品代表；可從技術來源查閱相關原廠。')}</p>`;return `<p class="company-note">${esc(note)}</p>`+t.companies.map(id=>{const c=COST_COMPANIES[id];return `<div class="company"><div><b>${c[0]}</b> <span>${c[1]} · ${c[2]}</span></div><p>${esc(t.companyRoles?.[id]||c[3])}</p>${refs(t.companySources?.[id]||[c[4]])}</div>`}).join('')}

function renderList(){const q=$('#search').value.toLowerCase().trim(),list=TERMS.filter(t=>(cat<0||t.cat===cat)&&(!q||[t.title,t.en,t.one,t.body,t.inputs,t.account,...t.companies.map(id=>COST_COMPANIES[id].join(' '))].join(' ').toLowerCase().includes(q)));$('#results-count').textContent=`${list.length} 個條目`;$('#terms').innerHTML=list.length?list.map(t=>`<button class="term-button ${t.id===selected?'selected':''}" data-term="${t.id}" aria-pressed="${t.id===selected}"><span>${t.title}</span><small>${t.en}</small></button>`).join(''):'<p class="empty">找不到相符名詞。試試「光阻」「折舊」或英文縮寫。</p>';$('#categories').innerHTML=[['全部',-1],...CATEGORIES.map((c,i)=>[c[0],i])].map(([n,i])=>`<button data-cat="${i}" class="${cat===i?'active':''}" aria-pressed="${cat===i}">${n}</button>`).join('')}
function selectTerm(id,scroll=false){const t=term(id);if(!t)return;selected=id;renderList();$('#detail').innerHTML=`<div class="detail-top"><span class="pill">${CATEGORIES[t.cat][0]}</span><button class="text-btn" data-copy="${t.id}">複製條目連結</button></div><h3 tabindex="-1" id="detail-title">${t.title}</h3><div class="english">${t.en}</div><p class="definition">${t.one}</p><p>${t.body}</p><div class="source-inline">技術／原則來源：${refs(t.sources)}</div><div class="role-grid"><div class="role"><h4>先看用途與耗用／取得</h4><p>${t.inputs}</p></div><div class="role"><h4>再看成本由什麼帶動</h4><p>${t.driver}</p></div></div><div class="account-note"><span class="eyebrow">ACCOUNTING APPLICATION / 教學歸集</span><h4>最後判斷如何歸集</h4><p>${t.account}</p><p class="small">上述內容把一般會計原則連到製程，供教學使用。它不是台積電公開的內部科目、成本率或分錄。實務上須核對合約、用途與採用準則。</p></div><div class="pitfall"><b>判斷時別混淆</b><p>${t.pitfall}</p></div><h4>台股代表公司與實際分工</h4>${companyHTML(t)}<p class="small">公司對照查核：2026-09-09；掛牌資料：2026-09-08。產品相符不代表供應台積電特定節點；來源連結可查核公司實際業務。</p><div class="related"><span>下一步可看</span>${t.related.map(id=>`<button data-term="${id}">${term(id).title} ↗</button>`).join('')}</div>`;if(scroll){$('#detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});$('#detail-title').focus({preventScroll:true})}}
window.selectPart=(id,open=false)=>{const t=term(id);if(!t)return;$('#scene-side').innerHTML=`<span class="eyebrow">SELECTED COMPONENT / 部件</span><h3>${t.title}</h3><p>${t.one}</p><div class="scene-role"><b>成本由什麼帶動？</b><p>${t.driver}</p></div><div class="scene-role"><b>會計判斷 · 教學</b><p>${t.account}</p></div><button class="primary-btn" data-term="${t.id}">查看用途、耗用與來源 ↗</button><div class="scene-source">${refs(t.sources.slice(0,2))}</div>`;document.querySelectorAll('[data-part]').forEach(b=>{b.classList.toggle('active',b.dataset.part===id);b.setAttribute('aria-pressed',b.dataset.part===id)});window.dispatchEvent(new CustomEvent('partselect',{detail:id}));if(open)window.dispatchEvent(new CustomEvent('partopen'))};
function setScene(id){const s=SCENES[id];if(!s)return;window.currentScene=id;$('#scene-index').textContent=s.en;$('#scene-title').textContent=s.title;$('#scene-subtitle').textContent=s.sub;document.querySelectorAll('[data-scene]').forEach(b=>{b.classList.toggle('active',b.dataset.scene===id);b.setAttribute('aria-pressed',b.dataset.scene===id)});$('#scene-key').innerHTML=s.parts.map(([id,label])=>`<button data-part="${id}">${label}</button>`).join('');$('#explode').value=id==='facility'?25:45;$('#explode-value').textContent=$('#explode').value+'%';selectPart(s.default);window.dispatchEvent(new CustomEvent('scenechange',{detail:id}))}
function computeCosts(q,y,f,v,n=10000,d=100){const rate=f/Math.max(n,q),absorbed=rate*q,unallocated=Math.max(0,f-absorbed),inventory=v+rate,economic=v+f/q,good=q*d*y;return {rate,absorbed,unallocated,inventory,economic,die:economic/(d*y),good,total:f+v*q}}
window.computeCosts=computeCosts;
const num=(n,d=0)=>n.toLocaleString('zh-TW',{maximumFractionDigits:d,minimumFractionDigits:d});
function sim(){const q=+$('#volume').value,y=+$('#yield').value/100,f=+$('#fixed').value*1000000,v=+$('#variable').value,r=computeCosts(q,y,f,v);$('#volume-out').textContent=num(q)+' 片 / 月';$('#yield-out').textContent=num(y*100)+'%';$('#fixed-out').textContent=num(f/1000000)+' 百萬元 / 月';$('#variable-out').textContent=num(v)+' 元 / 片';$('#utilization').textContent=num(q/100,0)+'%';$('#inventory-cost').textContent=num(r.inventory,0);$('#economic-cost').textContent=num(r.economic,0);$('#die-cost').textContent=num(r.die,2);$('#unallocated').textContent=num(r.unallocated/1000000,2)+' 百萬元';$('#absorbed').textContent=num(r.absorbed/1000000,2)+' 百萬元';$('#cost-bar').style.width=(r.absorbed/f*100)+'%';$('#sim-explanation').innerHTML=q<10000?`產量低於正常產能。每片分攤的固定製造費為 <b>${num(r.rate)} 元</b>，未分攤的 <b>${num(r.unallocated/1000000,2)} 百萬元</b>列為當期費用。未分攤的固定製造費不計入存貨；經濟成本則包含本期全部投入。`:`產量達到或超過正常產能。固定成本全數分配至實際產出；每片分攤 <b>${num(r.rate,0)} 元</b>。此處以 max（正常產能，實際產量）作簡化示範。產量高於正常產能時降低每片分攤額，避免分攤的固定製造費超過實際發生金額。`;$('#sim-good').textContent=`合格晶粒：${num(r.good)} 顆；每片固定可切 100 顆的假設，不含後續封裝費。`}
const ACCOUNTS={machine:['購置生產設備','符合條件支出 → 建造中資產 → 可使用後轉 PPE → 折舊進製造費用 → 在製品／製成品 → 銷貨成本','購買設備的現金支出與折舊分屬不同時間尺度，不能同時加進單片成本。','ias16'],chemical:['購買與耗用化學品','購入原料／耗材 → 領用 → 批次直接成本或製造費用 → 在製品 → 完工轉出 → 隨銷售轉成本','採購、領料、實際耗用、報廢與回收是不同事件，應保留可勾稽的數量紀錄。','ias2'],idle:['產能不足的固定成本','固定製造費用 → 依正常產能分攤 → 分攤部分進生產成本；未分攤部分當期費用化','產量較低時，不能任意墊高每單位存貨成本。','capacity'],research:['研究用工程批','專案領料＋人員時間＋設備使用 → 研究活動成本 → 當期研發費用','開發活動是否符合無形資產認列條件，須另行判斷；不能一律套用研究階段的費用化結論。','ias38'],customer:['客戶提供的裸晶','客供料代管數量 → 加工與追蹤 → 返還／交付；自有加工投入另行歸集','先核對所有權與合約。代管料件的估值不是自己的採購成本。','ias2']};
function account(id){const a=ACCOUNTS[id];document.querySelectorAll('[data-account]').forEach(b=>{b.classList.toggle('active',b.dataset.account===id);b.setAttribute('aria-pressed',b.dataset.account===id)});$('#account-flow').innerHTML=`<h3>${a[0]}</h3><div class="flowline">${a[1].split(' → ').map((s,i)=>`<div><small>${String(i+1).padStart(2,'0')}</small>${s}</div>`).join('')}</div><p>${a[2]}</p><div class="source-inline">${refs([a[3]])}</div>`}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-term]');if(b){selectTerm(b.dataset.term,true);history.replaceState(null,'','#term='+b.dataset.term);return}b=e.target.closest('[data-cat]');if(b){cat=+b.dataset.cat;renderList();return}b=e.target.closest('[data-scene]');if(b){setScene(b.dataset.scene);return}b=e.target.closest('[data-part]');if(b){selectPart(b.dataset.part,true);return}b=e.target.closest('[data-account]');if(b){account(b.dataset.account);return}b=e.target.closest('[data-copy]');if(b){const u=new URL(location.href);u.hash='term='+b.dataset.copy;try{await navigator.clipboard.writeText(u.href);b.textContent='已複製'}catch{history.replaceState(null,'',u.href);b.textContent='已更新網址，可複製網址列'}}});
$('#search').addEventListener('input',renderList);$('#clear-search').addEventListener('click',()=>{$('#search').value='';cat=-1;renderList();$('#search').focus()});$('#explode').addEventListener('input',e=>{$('#explode-value').textContent=e.target.value+'%';window.dispatchEvent(new CustomEvent('explodechange',{detail:e.target.value/100}))});['volume','yield','fixed','variable'].forEach(id=>$('#'+id).addEventListener('input',sim));$('#reset-sim').addEventListener('click',()=>{$('#volume').value=7000;$('#yield').value=80;$('#fixed').value=30;$('#variable').value=1000;sim()});
$('#cost-termcount').textContent=TERMS.length+' 個名詞與成本因子';$('#source-list').innerHTML=Object.entries(COST_SOURCES).map(([id,s],i)=>`<details><summary><span class="source-number">${String(i+1).padStart(2,'0')}</span>${esc(s[0])}</summary><p>${esc(s[2])}</p><a href="${s[1]}" target="_blank" rel="noopener">開啟原始來源 ↗</a></details>`).join('');
renderList();selectTerm('raw');setScene('fabflow');sim();account('machine');
function route(){const id=decodeURIComponent(location.hash.replace('#term=',''));if(location.hash.startsWith('#term=')&&term(id))selectTerm(id,true)}route();window.addEventListener('hashchange',route);
